assistant.body:
.order select,
.order input {
  font: inherit;
  padding: 8px 12px;
  border: 1px solid #ccc;
  border-radius: 4px;
  background-color: #fff;
}

.order select,
.order input[type="search"] {
  -webkit-appearance: none;
  appearance: none;
}

.order input[type="search"]::-webkit-search-decoration,
.order input[type="search"]::-webkit-search-cancel-button {
  -webkit-appearance: none;
}

.order select {
  padding-right: 32px;
  background-image:
    linear-gradient(45deg, transparent 50%, currentColor 50%),
    linear-gradient(135deg, currentColor 50%, transparent 50%);
  background-position:
    calc(100% - 18px) 50%,
    calc(100% - 13px) 50%;
  background-size: 5px 5px;
  background-repeat: no-repeat;
}

.order input[type="number"]::-webkit-inner-spin-button,
.order input[type="number"]::-webkit-outer-spin-button {
  -webkit-appearance: none;
  margin: 0;
}

.order input[type="number"] {
  -moz-appearance: textfield;
  appearance: textfield;
}
